uint32_t ref_infer(const int8_t img[REF_IMG_PIXELS], int32_t logits[REF_N_CLASSES]) {
    PROF_BEGIN();
    widen_img(img);   // counted in the conv1 stage
    for (int c = 0; c < 80; c++) {
        conv1_ch(img16, conv1_kp + 6 * c, ch16_a);
        PROF_STAGE(0);
        dw1_ch(ch16_a, dw1_kp + 6 * c, ch16_b);
        PROF_STAGE(1);
        pool1_ch(ch16_b, ch16_a);
        PROF_STAGE(2);
        dw2_ch(ch16_a, dw2_kp + 6 * c, ch_a);
        PROF_STAGE(3);
        pool2_ch(ch_a, feat + 4 * c);
        PROF_STAGE(4);
    }
    norm0(feat, act);
    fc1(act, acc);
    PROF_STAGE(5);
    norm1(acc, act);
    fc2(act, acc);
    PROF_STAGE(6);
    norm2(acc, act);
    fc3(act, logits);
    PROF_STAGE(7);
    uint32_t best = 0;
    for (uint32_t i = 1; i < 10; i++) if (logits[i] > logits[best]) best = i;
    return best;
}
